#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
import os
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Extract YYYY-MM-DD HH:MM:SS from the start of a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of_ts = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff_dt = as_of_dt.timestamp() - 7 * 86400  # 7 days before AS_OF

    log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "app.log")
    archive_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "archive.log")

    if not os.path.exists(log_path):
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    keep = []
    archive = []

    with open(log_path, "r") as f:
        for line in f:
            line = line.rstrip("\n")
            dt = parse_timestamp(line)
            if dt is not None and dt.timestamp() < cutoff_dt:
                archive.append(line)
            else:
                keep.append(line)

    # Append archived entries to archive.log
    with open(archive_path, "a") as f:
        for entry in archive:
            f.write(entry + "\n")

    # Rewrite app.log with kept entries
    with open(log_path, "w") as f:
        for entry in keep:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

