"""Rotate app.log entries older than 7 days before a given timestamp into archive.log."""

import sys
from datetime import datetime, timedelta, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a leading 'YYYY-MM-DD HH:MM:SS ' prefix from *line*."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = datetime.fromtimestamp(int(sys.argv[1]), tz=timezone.utc)
    except (ValueError, OSError):
        print(f"Error: AS_OF must be a valid Unix timestamp in seconds", file=sys.stderr)
        sys.exit(1)

    threshold = as_of - timedelta(days=7)

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt < threshold:
            archive.append(line)
        else:
            keep.append(line)

    with open("archive.log", "a") as f:
        f.writelines(archive)

    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

